<script setup lang="ts">
import { ref, computed, onMounted, nextTick, onUnmounted } from 'vue';
import { Compass, MessageCircle, BookOpen, LibraryBig, Settings2, ArrowUp, ArrowUpRight, Plus, ChevronRight, Leaf, Sparkles, ShieldCheck, Check, LockKeyhole, X, LoaderCircle, Square, Download, ExternalLink, Trash2, ArrowLeft, PanelLeftClose, Feather, Swords, Gem, UserRound, Search, RefreshCw } from '@lucide/vue';
import { api, streamChat } from './api';
import {sessionSync,type SessionSignal} from './session-sync';
import type { Bootstrap, Session, SessionView, Settings, Message, Evidence, ScopeSuggestion } from './types';
import WindSpirit from './components/WindSpirit.vue';
import Landscape from './components/Landscape.vue';
import PetWindow from './components/PetWindow.vue';
import StoryCatalog from './components/StoryCatalog.vue';
import ProgressPicker from './components/ProgressPicker.vue';

const window=globalThis.window;
const isPet=window.location.pathname==='/pet';
const desktop=!!window.windborne;
let localSending=false,syncTimer:ReturnType<typeof setTimeout>|undefined,remotePoll:ReturnType<typeof setInterval>|undefined;
const shared=isPet?null:sessionSync(receiveSignal);
const route=ref(window.location.pathname==='/'?'/chat':window.location.pathname);
const boot=ref<Bootstrap>();const session=ref<Session>();const messages=ref<Message[]>([]);const suggestions=ref<string[]>([]);
const question=ref('');const busy=ref(false);const status=ref('');const error=ref('');const toast=ref('');const booting=ref(true);
const scrollArea=ref<HTMLElement>();const textarea=ref<HTMLTextAreaElement>();let abort:AbortController|undefined;let toastTimer:ReturnType<typeof setTimeout>|undefined;
const evidence=ref<Evidence>();const library=ref<Evidence[]>([]);const librarySearch=ref('');
const selectedTopic=ref<number>();
const deleting=ref(false),deleteTarget=ref<Session>();

const progressOpen=ref(false);const pendingProgress=ref(1);const changingProgress=ref(false);
const saving=ref(false);const testing=ref(false);const settingsError=ref('');
const form=ref({mode:'cloud',baseUrl:'',model:'',apiKey:'',detail:'normal'});
const currentStage=computed(()=>boot.value?.pack.stages.find(s=>s.id===session.value?.progress));
const independent=computed(()=>currentStage.value?.scopeMode==='independent');
const visibleTimeline=computed(()=>boot.value?.pack.stages.filter(s=>independent.value?s.id===session.value?.progress:s.id<=3)??[]);
const mainProgressStages=computed(()=>(boot.value?.pack.stages??[]).filter(s=>s.isMainChapter).sort((a,b)=>(b.chapterOrder??0)-(a.chapterOrder??0)));
const topicStage=computed(()=>boot.value?.pack.stages.find(s=>s.id===selectedTopic.value));
const filteredLibrary=computed(()=>library.value.filter(r=>`${r.topic}${r.text}${r.task}`.includes(librarySearch.value.trim())));
const lastFollowups=computed(()=>messages.value.filter(m=>m.role==='assistant').at(-1)?.followups ?? suggestions.value);
const navItems=[{path:'/chat',label:'剧情对话',icon:MessageCircle},{path:'/catalog',label:'剧情目录',icon:Compass},{path:'/journal',label:'旅程档案',icon:BookOpen},{path:'/reference',label:'资料图鉴',icon:LibraryBig}];
function notify(value:string){toast.value=value;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3600);}
function syncForm(settings:Settings){form.value={mode:settings.mode,baseUrl:settings.baseUrl,model:settings.model,apiKey:'',detail:settings.detail};}
async function refreshBoot(){const data=await api<Bootstrap>('/api/bootstrap');boot.value=data;return data;}
function assignView(view:SessionView,publish=true){session.value=view.session;messages.value=view.messages;suggestions.value=view.suggestions;if(!localSending)busy.value=!!view.busy;localStorage.setItem('windborne-session',view.session.id);if(publish)shared?.publish({type:'session',sessionId:view.session.id});}
function receiveSignal(signal:SessionSignal){if(localSending)return;if(signal.type==='busy'&&signal.sessionId===session.value?.id){busy.value=!!signal.busy;status.value=signal.busy?'桌宠正在讲解…':'';if(signal.busy)return;}clearTimeout(syncTimer);syncTimer=setTimeout(()=>void refreshShared(),60);}
async function refreshShared(){if(localSending||booting.value||deleting.value)return;try{const data=await refreshBoot();const id=localStorage.getItem('windborne-session');if(!id||!data.sessions.some(s=>s.id===id)){const next=data.sessions[0];assignView(next?await api<SessionView>(`/api/sessions/${next.id}`):await api<SessionView>('/api/sessions',{method:'POST',body:JSON.stringify({progress:session.value?.progress??1})}));evidence.value=undefined;if(route.value==='/journal')await loadLibrary();return;}const view=await api<SessionView>(`/api/sessions/${id}`);if(localSending||localStorage.getItem('windborne-session')!==id)return;const changed=session.value?.id!==view.session.id||session.value?.progress!==view.session.progress;assignView(view,false);status.value=view.busy?'桌宠正在讲解…':'';if(changed){evidence.value=undefined;progressOpen.value=false;}if(route.value==='/journal')await loadLibrary();await scrollToBottom();}catch(e){notify((e as Error).message);}}
async function initialize(){booting.value=true;error.value='';try{const data=await refreshBoot();syncForm(data.settings);const id=localStorage.getItem('windborne-session');const found=data.sessions.find(s=>s.id===id) ?? data.sessions[0];if(found)assignView(await api<SessionView>(`/api/sessions/${found.id}`));else assignView(await api<SessionView>('/api/sessions',{method:'POST',body:JSON.stringify({progress:1})}));await refreshBoot();if(route.value==='/journal')await loadLibrary();await scrollToBottom();}catch(e){error.value=(e as Error).message;}finally{booting.value=false;}}
async function navigate(path:string){route.value=path;history.pushState({},'',path);if(path==='/journal')await loadLibrary();if(path==='/settings' && boot.value)syncForm(boot.value.settings);}
function popstate(){route.value=location.pathname;if(route.value==='/journal')void loadLibrary();}
async function newSession(){if(busy.value)return;try{assignView(await api<SessionView>('/api/sessions',{method:'POST',body:JSON.stringify({progress:session.value?.progress ?? 1})}));await refreshBoot();await navigate('/chat');}catch(e){notify((e as Error).message);}}
async function switchSession(id:string){if(busy.value){notify('请先停止当前讲解');return;}try{assignView(await api<SessionView>(`/api/sessions/${id}`));evidence.value=undefined;await navigate('/chat');await scrollToBottom();}catch(e){notify((e as Error).message);}}
async function deleteSession(){const target=deleteTarget.value;if(!target||busy.value||deleting.value)return;deleting.value=true;try{await api('/api/sessions/'+target.id,{method:'DELETE'});shared?.publish({type:'deleted',sessionId:target.id});const active=session.value?.id===target.id,progress=session.value?.progress??1;deleteTarget.value=undefined;if(active){messages.value=[];question.value='';evidence.value=undefined;library.value=[];}const data=await refreshBoot();if(active){const next=data.sessions[0];assignView(next?await api<SessionView>('/api/sessions/'+next.id):await api<SessionView>('/api/sessions',{method:'POST',body:JSON.stringify({progress})}));await refreshBoot();if(route.value==='/journal')await loadLibrary();}notify('对话已删除');}catch(e){notify((e as Error).message);}finally{deleting.value=false;}}
async function loadLibrary(){if(!session.value)return;try{library.value=(await api<{records:Evidence[]}>(`/api/library?sessionId=${session.value.id}`)).records;}catch(e){notify((e as Error).message);}}
async function scrollToBottom(){await nextTick();scrollArea.value?.scrollTo({top:scrollArea.value.scrollHeight,behavior:'smooth'});}
async function openEntity(action:ScopeSuggestion){if(busy.value)return;busy.value=true;try{assignView(await api<SessionView>('/api/sessions',{method:'POST',body:JSON.stringify({progress:action.stageId})}));evidence.value=undefined;await refreshBoot();await navigate('/chat');busy.value=false;await send(action.question);}catch(e){notify((e as Error).message);}finally{busy.value=false;}}
async function send(value?:string){const text=(value ?? question.value).trim();if(!text || busy.value || !session.value)return;if(text==='开放水仙十字结社专题（含后续剧情）'){try{assignView(await api<SessionView>('/api/sessions',{method:'POST',body:JSON.stringify({progress:1900000001})}));await refreshBoot();await send('水仙十字结社是什么');}catch(e){notify((e as Error).message);}return;}question.value='';localSending=true;busy.value=true;shared?.publish({type:'busy',sessionId:session.value.id,busy:true});status.value='正在翻开这段故事…';abort=new AbortController();
  const tempUser:Message={id:'pending-user',role:'user',text};const tempAnswer:Message={id:'pending-answer',role:'assistant',sections:[],citations:[]};messages.value.push(tempUser,tempAnswer);await scrollToBottom();
  try{await streamChat(session.value.id,text,abort.signal,event=>{
    const pending=messages.value.find(m=>m.id==='pending-answer');
    if(event.type==='user'){const index=messages.value.findIndex(m=>m.id==='pending-user');if(index>=0)messages.value[index]=event.message;shared?.publish({type:'updated',sessionId:session.value?.id});}
    if(event.type==='status')status.value=event.text;
    if(event.type==='meta' && pending)Object.assign(pending,{mode:event.mode,warning:event.warning,status:event.status,citations:event.citations});
    if(event.type==='section' && pending)pending.sections!.push({text:'',kind:event.kind,citationIds:event.citationIds});
    if(event.type==='delta' && pending)pending.sections![event.index]!.text+=event.text;
    if(event.type==='done'){const index=messages.value.findIndex(m=>m.id==='pending-answer');if(index>=0)messages.value[index]=event.message;}
    void scrollToBottom();
  });await refreshBoot();}
  catch(e){const pending=messages.value.find(m=>m.id==='pending-answer');if(pending)Object.assign(pending,{sections:[{text:abort?.signal.aborted?'已停止这次讲解。你可以换个问题继续。':(e as Error).message,kind:'notice',citationIds:[]}],citations:[],mode:'notice'});}
  finally{localSending=false;busy.value=false;shared?.publish({type:'busy',sessionId:session.value?.id,busy:false});shared?.publish({type:'updated',sessionId:session.value?.id});status.value='';await scrollToBottom();textarea.value?.focus();}
}
function onEnter(e:KeyboardEvent){if(e.key==='Enter' && !e.shiftKey && !e.isComposing){e.preventDefault();void send();}}
async function showEvidence(id:string){if(!session.value)return;try{evidence.value=await api<Evidence>(`/api/evidence/${id}?sessionId=${session.value.id}`);}catch(e){notify((e as Error).message);}}
function citationNumber(message:Message,id:string){return (message.citations?.findIndex(c=>c.id===id) ?? -1)+1;}
async function startTopic(){if(selectedTopic.value===undefined||busy.value)return;try{assignView(await api<SessionView>('/api/sessions',{method:'POST',body:JSON.stringify({progress:selectedTopic.value})}));selectedTopic.value=undefined;evidence.value=undefined;await refreshBoot();await navigate('/chat');await scrollToBottom();}catch(e){notify((e as Error).message);}}
function openProgress(){pendingProgress.value=session.value?.progress ?? 1;progressOpen.value=true;}
function chooseProgress(event:Event){const value=Number((event.target as HTMLSelectElement).value);if(!value)return;pendingProgress.value=value;progressOpen.value=true;(event.target as HTMLSelectElement).value='';}
async function changeProgress(){if(!session.value)return;changingProgress.value=true;try{assignView(await api<SessionView>(`/api/sessions/${session.value.id}`,{method:'PATCH',body:JSON.stringify({progress:pendingProgress.value})}));evidence.value=undefined;progressOpen.value=false;await refreshBoot();if(route.value==='/journal')await loadLibrary();notify('剧情范围已更新');}catch(e){notify((e as Error).message);}finally{changingProgress.value=false;}}
async function saveSettings(test=false){settingsError.value='';saving.value=true;try{const settings=await api<Settings>('/api/settings',{method:'PUT',body:JSON.stringify(form.value)});boot.value!.settings=settings;shared?.publish({type:'settings'});form.value.apiKey='';notify('设置已保存');if(test){testing.value=true;const result=await api<{message:string}>('/api/connection',{method:'POST',body:'{}'});notify(result.message);}}catch(e){settingsError.value=(e as Error).message;}finally{saving.value=false;testing.value=false;}}
async function removeKey(){try{const settings=await api<Settings>('/api/key',{method:'DELETE'});boot.value!.settings=settings;shared?.publish({type:'settings'});syncForm(settings);notify('密钥已移除，已切回资料讲解');}catch(e){settingsError.value=(e as Error).message;}}
function external(url:string){if(window.windborne)window.windborne.openExternal(url);else window.open(url,'_blank','noopener,noreferrer');}
function exportNotes(){if(!session.value)return;const lines=[`# 世界树-提瓦特 · ${session.value.title}`,`剧情范围：${currentStage.value?.title}`,''];for(const m of messages.value){if(m.role==='user')lines.push(`## 旅行者\n${m.text}\n`);else{lines.push('## 风语精灵');for(const s of m.sections ?? [])lines.push(`${s.kind==='inference'?'【分析推断】':''}${s.text}`);for(const c of m.citations ?? [])lines.push(`- 出处：[${c.task} · ${c.section}](${c.source.url})`);lines.push('');}}const url=URL.createObjectURL(new Blob([lines.join('\n\n')],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`世界树-提瓦特-${new Date().toISOString().slice(0,10)}.md`;a.click();URL.revokeObjectURL(url);notify('手记已导出');}
function escape(e:KeyboardEvent){if(e.key==='Escape'){if(!deleting.value)deleteTarget.value=undefined;selectedTopic.value=undefined;evidence.value=undefined;progressOpen.value=false;}}
onMounted(()=>{if(!isPet){void initialize();remotePoll=setInterval(()=>{if(busy.value&&!localSending)void refreshShared();},1500);window.addEventListener('focus',refreshShared);window.addEventListener('popstate',popstate);window.addEventListener('keydown',escape);}});
onUnmounted(()=>{abort?.abort();shared?.close();clearTimeout(syncTimer);clearInterval(remotePoll);window.removeEventListener('focus',refreshShared);clearTimeout(toastTimer);window.removeEventListener('popstate',popstate);window.removeEventListener('keydown',escape);});
</script>

<template>
  <PetWindow v-if="isPet" />
  <div v-else-if="booting || !boot" class="loading-screen"><Compass :size="40"/><h1>世界树-提瓦特</h1><p>{{ error || '正在翻开旅途的第一页…' }}</p><button v-if="error" class="button primary" @click="initialize"><RefreshCw :size="16"/>重新打开</button></div>
  <div v-else class="app-shell">
    <aside class="sidebar">
      <a class="brand" href="/chat" @click.prevent="navigate('/chat')"><span class="brand-mark"><Compass :size="28" :stroke-width="1.4"/></span><span><strong>世界树-提瓦特</strong><small>IRMINSUL-TEYVAT</small></span></a>
      <button class="new-chat" @click="newSession" :disabled="busy"><Plus :size="18"/>开启一段对话<span>↗</span></button>
      <nav aria-label="主要导航"><button v-for="item in navItems" :key="item.path" :class="['nav-item',{active:route===item.path}]" @click="navigate(item.path)"><component :is="item.icon" :size="18" :stroke-width="1.6"/>{{item.label}}<span v-if="item.path==='/reference'" class="soon-dot"></span></button></nav>
      <div class="history-label">旅途中的对话 <span>{{boot.sessions.length}}</span></div>
      <div class="history-list"><div v-for="item in boot.sessions" :key="item.id" class="history-row"><button :class="['history-item',{selected:session?.id===item.id}]" :disabled="deleting" @click="switchSession(item.id)"><span class="history-dot"></span><span>{{item.title}}</span></button><button class="icon-button history-delete" :aria-label="'删除对话：'+item.title" :title="busy?'请先停止讲解，再删除对话':'删除对话'" :disabled="busy||deleting" @click="deleteTarget=item"><Trash2 :size="14"/></button></div><p v-if="!boot.sessions.length">故事从第一句话开始。</p></div>
      <div class="sidebar-footer"><div class="little-note"><Feather :size="20"/><p>让风记住旅途，<br>让故事有迹可循。</p></div><button :class="['nav-item',{active:route==='/settings'}]" @click="navigate('/settings')"><Settings2 :size="18"/>模型与偏好</button><div class="build-label"><span>剧情互动验证版</span><span>v{{boot.pack.version}}</span></div></div>
    </aside>
    <main class="main-area">
      <header class="topbar"><div class="breadcrumbs"><Leaf :size="15"/><span>提瓦特</span><ChevronRight :size="13"/><strong>{{currentStage?.category??'蒙德篇'}}</strong></div><div class="top-actions"><button class="mode-badge" @click="navigate('/settings')"><span :class="['status-dot',{online:boot.settings.mode==='cloud' && boot.settings.ready}]"></span>{{boot.settings.mode==='cloud' && boot.settings.ready?'在线讲解已配置':'资料讲解模式'}}</button><button v-if="desktop" class="icon-button" aria-label="收起为桌宠" title="收起为桌宠" @click="window.windborne?.hideChat()"><PanelLeftClose :size="18"/></button><span class="avatar">旅</span></div></header>

      <div v-if="route==='/chat' || route==='/'" class="chat-layout">
        <section class="conversation">
          <div class="conversation-toolbar"><div><span class="eyebrow">STORIES ON THE WIND</span><h2>与风同行</h2></div><div class="toolbar-tools"><button class="icon-button compact-progress" aria-label="新对话" :disabled="busy" @click="newSession"><Plus :size="16"/></button><button class="text-button compact-progress" :disabled="busy" @click="openProgress"><ShieldCheck :size="15"/>剧情进度</button><button class="text-button" :disabled="!messages.length || busy" @click="exportNotes"><Download :size="15"/>导出手记</button></div></div>
          <div ref="scrollArea" class="conversation-scroll">
            <div v-if="!messages.length" class="welcome">
              <div class="hero"><Landscape/><div class="hero-overlay"></div><div class="hero-copy"><span class="hero-kicker"><span></span>{{independent?currentStage?.title:'蒙德 · 故事的起点'}}</span><h1>每一段旅途，<br>都有值得回味的故事。</h1><p>从一场相遇开始，听风慢慢讲给你。</p><span class="hero-footnote">{{independent?currentStage?.subtitle:'序章 · 捕风的异乡人'}}</span></div></div>
              <div class="welcome-message"><div class="assistant-avatar"><WindSpirit/></div><div><div class="speaker-name">风语精灵 <span>你的剧情旅伴</span></div><p>你好，旅行者。想回顾一段经历，还是聊聊某个人的心事？<br>我会带上故事的出处，也会替你守好还没走到的旅途。</p></div></div>
              <div class="suggestions-title"><Sparkles :size="15"/>不妨从这里聊起</div><div class="question-grid"><button v-for="(item,i) in suggestions" :key="item" @click="send(item)"><span class="question-index" aria-hidden="true">0{{i+1}}</span><span>{{item}}</span><ArrowUpRight :size="16"/></button></div>
              <div class="scope-note"><ShieldCheck :size="15"/><span>{{independent?currentStage?.summary:`当前只讲到「${currentStage?.title}」，后续故事先替你收好。`}}</span></div>
            </div>
            <div v-else class="message-list">
              <article v-for="message in messages" :key="message.id" :class="['message',message.role]">
                <template v-if="message.role==='user'"><div class="user-bubble">{{message.text}}</div><span class="user-mini">旅</span></template>
                <template v-else><div class="assistant-avatar small"><WindSpirit :state="busy && message.id==='pending-answer'?'thinking':'idle'"/></div><div class="answer-body"><div class="speaker-name">风语精灵<span v-if="message.mode==='cloud'" class="answer-mode">AI 讲解</span><span v-else-if="message.mode==='offline' || message.mode==='fallback'" class="answer-mode">资料整理</span></div><div v-if="busy && message.id==='pending-answer' && !message.sections?.length" class="thinking"><LoaderCircle :size="16" class="spin"/>{{status}}</div><div v-if="message.warning" class="answer-warning">{{message.warning}}</div><div v-for="(section,i) in message.sections" :key="i" :class="['answer-section',section.kind]"><span v-if="section.kind==='inference'" class="inference-label"><Sparkles :size="12"/>分析推断</span><p>{{section.text}}<button v-for="id in section.citationIds" :key="id" class="inline-citation" :aria-label="`查看出处 ${citationNumber(message,id)}`" @click="showEvidence(id)">{{citationNumber(message,id)}}</button></p></div><div v-if="message.citations?.length" class="source-chips"><button v-for="(citation,index) in message.citations" :key="citation.id" @click="showEvidence(citation.id)"><BookOpen :size="12"/><span>{{index+1}} · {{citation.topic}}</span><ArrowUpRight :size="12"/></button></div><button v-if="message.status==='reference'" class="button subtle" @click="navigate('/reference')">查看资料图鉴占位页<ArrowUpRight :size="15"/></button></div></template>
              </article>
              <div v-if="!busy && messages.at(-1)?.scopeSuggestions?.length" class="followups"><span>关联资料 · 开放后新建对话</span><button v-for="action in messages.at(-1)?.scopeSuggestions" :key="action.stageId" @click="openEntity(action)">{{action.label}}</button></div>
              <div v-if="!busy && lastFollowups.length" class="followups"><span>接着聊聊</span><button v-for="item in lastFollowups" :key="item" @click="send(item)">{{item}}<ArrowUpRight :size="13"/></button></div>
            </div>
          </div>
          <div class="composer-wrap"><div class="composer"><label class="sr-only" for="question">输入剧情问题</label><textarea id="question" ref="textarea" v-model="question" maxlength="1000" :disabled="busy" placeholder="有什么故事，想和我聊聊？" rows="2" @keydown="onEnter"></textarea><div class="composer-bottom"><span><Feather :size="14"/>{{busy?'正在沿着故事寻找答案…':'Enter 发送 · Shift + Enter 换行'}}</span><button v-if="busy" :disabled="!localSending" class="send-button stop" aria-label="停止讲解" @click="abort?.abort()"><Square :size="15" fill="currentColor"/></button><button v-else class="send-button" :disabled="!question.trim()" aria-label="发送问题" @click="send()"><ArrowUp :size="21"/></button></div></div><p class="composer-note">{{boot.settings.mode==='cloud'?'AI 讲解可能有误，重要细节可展开出处核对。':'基于精选资料整理；在设置中接入模型可获得自由讲解。'}}</p></div>
        </section>
        <aside class="journey-panel"><div class="journey-heading"><span>这段旅程</span><Compass :size="17"/></div><div class="chapter-tag">{{currentStage?.category??'序章 · 第一幕'}}</div><h3>{{independent?currentStage?.title:'初遇安柏 · 走进蒙德'}}</h3><div class="journey-line"></div><label class="journey-scope-label" for="journey-chapter">选择主线进度</label><select id="journey-chapter" class="journey-chapter" aria-label="右侧剧情章节" :disabled="busy" @change="chooseProgress"><option value="">选择章节…</option><option v-for="stage in mainProgressStages" :key="stage.id" :value="stage.id">{{stage.subtitle}} · {{stage.title}}</option></select><p class="progress-hint">选择后可询问该章及之前的已入库主线剧情。</p><p v-if="currentStage?.isMainChapter" class="progress-hint">已开放从开篇至「{{currentStage.title}}」（含本章），共 {{(currentStage.chapterOrder??0)+1}} 个主线章节。</p><div class="timeline"><div v-for="stage in visibleTimeline" :key="stage.id" :class="['timeline-item',{unlocked:stage.id<=(session?.progress ?? 1),current:stage.id===session?.progress}]"><span class="timeline-dot"><Check v-if="stage.id<(session?.progress ?? 1)" :size="11"/><span v-else-if="stage.id===session?.progress"></span><LockKeyhole v-else :size="10"/></span><div><strong>{{stage.title}}</strong><small>{{stage.id<=(session?.progress ?? 1)?stage.subtitle:'尚未开放这段故事'}}</small></div></div></div><button class="progress-button" :disabled="busy" @click="openProgress"><ShieldCheck :size="16"/>调整剧情进度<ChevronRight :size="14"/></button><p class="progress-hint">只展开你愿意知晓的部分。</p><div class="companion-card"><WindSpirit :state="busy?'thinking':'idle'"/><strong>风语精灵，在这里陪你</strong><p>你的每一个“为什么”，<br>都是重访旅途的开始。</p><button v-if="desktop" class="text-button" @click="window.windborne?.showPet()">在桌面上见<ArrowUpRight :size="13"/><span class="sr-only">显示桌宠</span></button><span v-else class="companion-tip">桌面版支持悬浮精灵</span></div><div class="archive-footnote"><BookOpen :size="13"/><span>{{independent?'独立主题 · '+currentStage?.subtitle:'精选资料包 · 3 段任务'}}<br>每次讲解均可回查出处</span></div></aside>
      </div>

      <StoryCatalog v-else-if="route==='/catalog'" :stages="boot.pack.stages" :busy="busy" @start="selectedTopic=$event" @entity="openEntity" @external="external"/>
      <section v-else-if="route==='/journal'" class="page-scroll journal-page"><div class="page-heading"><span class="eyebrow">A JOURNEY, REMEMBERED</span><h1>旅程档案</h1><p>把相遇、疑问与线索，放回故事发生的地方。</p></div><div class="library-tools"><label class="search-box"><Search :size="17"/><input v-model="librarySearch" aria-label="搜索剧情资料" placeholder="搜索人物、事件或资料内容…"/></label><button class="button subtle" :disabled="busy" @click="openProgress"><ShieldCheck :size="16"/>讲到 {{currentStage?.title}}</button></div><div class="library-summary"><span>已开放 {{library.length}} 条精选资料</span><span>原文短摘与资料整理分开呈现</span></div><div class="record-grid"><button v-for="record in filteredLibrary" :key="record.id" class="record-card" @click="showEvidence(record.id)"><span class="record-task"><BookOpen :size="13"/>{{record.task}}</span><h3>{{record.topic}}<ArrowUpRight :size="17"/></h3><p>{{record.text}}</p><span class="record-footer">{{record.contentType==='source'?'自动解析原文':record.branch?'包含对话选项说明':'资料整理'}}<span>查看出处 →</span></span></button></div><div v-if="!filteredLibrary.length" class="empty-state"><Search :size="28"/><h3>没有找到相关资料</h3><p>试试“安柏”“朋友”或“护送”。</p></div><p class="content-scope">{{boot.pack.coverage}}</p></section>

      <section v-else-if="route==='/reference'" class="page-scroll reference-page"><div class="page-heading"><span class="eyebrow">THE TRAVELER'S REFERENCE</span><h1>资料图鉴</h1><p>角色、武器与圣遗物的效果说明，会在这里与旅人见面。</p></div><div class="reference-banner"><div class="reference-symbol"><LibraryBig :size="42" :stroke-width="1"/></div><span class="coming-label">正在规划中</span><h2>为每一份力量，留一页清晰的说明。</h2><p>先一起读懂故事。效果与数值的固定页面，稍后补齐。</p></div><div class="reference-grid"><article v-for="item in [{title:'角色',icon:UserRound,text:'技能、天赋与命之座'},{title:'武器',icon:Swords,text:'属性与精炼效果'},{title:'圣遗物',icon:Gem,text:'套装与效果说明'}]" :key="item.title"><component :is="item.icon" :size="25" :stroke-width="1.3"/><h3>{{item.title}}</h3><p>{{item.text}}</p><span>敬请期待</span></article></div><button class="button primary back-to-story" @click="navigate('/chat')"><ArrowLeft :size="16"/>回到剧情对话</button></section>

      <section v-else-if="route==='/settings'" class="page-scroll settings-page"><div class="page-heading"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>模型与偏好</h1><p>选择讲解方式，让故事以你喜欢的节奏展开。</p></div><form class="settings-form" @submit.prevent="saveSettings(false)"><div class="settings-group"><h3><Sparkles :size="18"/>讲解方式</h3><div class="mode-options"><label :class="{chosen:form.mode==='offline'}"><input type="radio" v-model="form.mode" value="offline"/><span><strong>资料讲解</strong><small>离线检索精选资料，不需要密钥</small></span></label><label :class="{chosen:form.mode==='cloud'}"><input type="radio" v-model="form.mode" value="cloud"/><span><strong>在线模型讲解</strong><small>让模型结合证据自然地回答与追问</small></span></label></div></div><div class="settings-group"><h3><Settings2 :size="18"/>在线服务</h3><p class="field-help">支持 Chat Completions 兼容接口。填写服务商提供的地址与模型名。</p><label class="field-label" for="base-url">服务地址</label><input id="base-url" v-model="form.baseUrl" autocomplete="off" spellcheck="false" placeholder="https://你的模型服务/v1"/><label class="field-label" for="model-name">模型名称</label><input id="model-name" v-model="form.model" autocomplete="off" spellcheck="false" placeholder="服务商提供的模型 ID"/><div class="key-label"><label class="field-label" for="api-key">API Key</label><span v-if="boot.settings.hasKey"><Check :size="12"/>已设置，不回显</span></div><input id="api-key" v-model="form.apiKey" type="password" autocomplete="new-password" spellcheck="false" :placeholder="boot.settings.hasKey?'留空则保留已保存的密钥':'只在这里填写你的密钥'"/><p class="field-help key-help"><LockKeyhole :size="13"/>{{boot.settings.persistentKey?'密钥使用系统加密保存在本机。':'浏览器验证模式：密钥仅保留至本次服务退出。'}}<button v-if="boot.settings.hasKey" type="button" @click="removeKey">移除密钥</button></p><p class="privacy-note">启用在线讲解后，问题、必要的近期问题与检索到的剧情资料会发送至你配置的服务。连接测试也会发出一次请求。</p></div><div class="settings-group"><h3><Feather :size="18"/>讲解长度</h3><div class="length-options"><label v-for="item in [{value:'brief',title:'简短一点'},{value:'normal',title:'刚刚好'},{value:'detailed',title:'详细展开'}]" :key="item.value" :class="{chosen:form.detail===item.value}"><input type="radio" v-model="form.detail" :value="item.value"/>{{item.title}}</label></div></div><div v-if="settingsError" class="form-error" role="alert">{{settingsError}}</div><div class="settings-actions"><button class="button primary" type="submit" :disabled="saving"><LoaderCircle v-if="saving && !testing" class="spin" :size="15"/><Check v-else :size="16"/>保存设置</button><button class="button subtle" type="button" :disabled="saving || !form.baseUrl || !form.model" @click="saveSettings(true)"><LoaderCircle v-if="testing" class="spin" :size="15"/>{{testing?'正在测试连接…':'保存并测试连接'}}</button></div></form><div class="about-note"><Compass :size="18"/><div><strong>世界树-提瓦特 · 验证版 {{boot.pack.version}}</strong><p>{{boot.pack.coverage}}<br>资料核对日期：{{boot.pack.verifiedAt}}。精灵与风景为本项目原创矢量插画。</p></div></div></section>
      <section v-else class="page-scroll empty-state"><h1>这页手记还没有内容</h1><button class="button primary" @click="navigate('/chat')">回到剧情对话</button></section>
    </main>
    <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="16"/>{{toast}}</div></Transition>
    <div v-if="evidence" class="modal-backdrop" @click.self="evidence=undefined"><section class="evidence-drawer" role="dialog" aria-modal="true" aria-labelledby="evidence-title"><button class="drawer-close icon-button" aria-label="关闭出处" @click="evidence=undefined"><X :size="20"/></button><span class="eyebrow">FOLLOW THE FOOTNOTES</span><h2 id="evidence-title">故事有迹可循</h2><div class="evidence-task"><BookOpen :size="16"/>{{evidence.task}}</div><h3>{{evidence.topic}}</h3><span class="small-label">{{evidence.contentType==='source'?'自动解析原文 · 尚未逐条核对':evidence.contentType==='outline'?'提纲导览 · 含待核对事项':'资料整理 · 非逐字台词'}}</span><p class="evidence-summary">{{evidence.text}}</p><template v-if="evidence.quote"><span class="small-label">原文短摘</span><blockquote><span class="quote-mark">“</span>{{evidence.quote}}<cite>—— {{evidence.speaker}}</cite></blockquote></template><p v-else-if="evidence.contentType!=='source'" class="excerpt-note">本条未附逐字摘录，可在来源页查看完整上下文。</p><div v-if="evidence.branch" class="branch-note"><strong>对话分支</strong><p>当前选项：{{evidence.branch.option}}。不同选项不能拼接为同一条经历。</p></div><div v-if="evidence.interpretation" class="interpretation-note"><span><Sparkles :size="13"/>分析推断</span><p>{{evidence.interpretation}}</p></div><dl class="provenance"><div><dt>剧情位置</dt><dd>{{evidence.section}}</dd></div><div><dt>整理来源</dt><dd>{{evidence.source.publisher}}</dd></div><div v-if="evidence.source.verificationLevel"><dt>核对层次</dt><dd>{{evidence.source.verificationLevel==='unreviewed-source'?'自动采集，未逐条核对':evidence.source.verificationLevel==='dialogue'?'对白片段核对':evidence.source.verificationLevel==='task-index'?'任务描述与流程':'公开检索摘录'}}</dd></div><div><dt>页面版本</dt><dd>{{evidence.source.revision}}</dd></div><div><dt>{{evidence.contentType==='source'?'采集日期':'整理日期'}}</dt><dd>{{evidence.verifiedAt}}</dd></div></dl><p v-if="evidence.source.note" class="excerpt-note">{{evidence.source.note}}</p><div v-if="evidence.sourcePages?.length" class="source-chips"><button v-for="page in evidence.sourcePages" :key="page.pageid" :disabled="busy" @click="selectedTopic=page.stageId;evidence=undefined">选择原文范围：{{page.title}}</button></div><p v-if="evidence.source.localDocument" class="excerpt-note">本地提纲：{{evidence.source.localDocument}} · {{evidence.source.locator}}</p><div v-if="evidence.source.links?.length" class="source-chips"><button v-for="link in evidence.source.links" :key="link.url" @click="external(link.url)">{{link.title}} ↗</button></div><button class="button primary source-link" @click="external(evidence.source.url)">{{evidence.contentType==='outline'?'查看提纲参考来源':'在 BWIKI 中阅读原文'}}<ExternalLink :size="15"/></button><p class="source-disclaimer">外部来源页可能包含当前进度之外的内容。<br>BWIKI 页面标注 CC BY-NC-SA 4.0。</p></section></div>
    <div v-if="deleteTarget" class="modal-backdrop centered" @click.self="!deleting&&(deleteTarget=undefined)"><section class="progress-modal" role="dialog" aria-modal="true" aria-labelledby="delete-title"><h2 id="delete-title">删除这段对话？</h2><p>“{{deleteTarget.title}}”的消息与引用记录将被删除，无法恢复。剧情资料和模型配置会保留。</p><div class="settings-actions"><button class="button subtle" :disabled="deleting" @click="deleteTarget=undefined">取消删除</button><button class="button primary" :disabled="busy||deleting" @click="deleteSession">{{deleting?'正在删除…':'确认删除对话'}}</button></div></section></div>
    <ProgressPicker v-if="progressOpen && boot" :stages="boot.pack.stages" :current="session?.progress??1" :initial="pendingProgress" :busy="changingProgress||busy" @close="progressOpen=false" @confirm="pendingProgress=$event;changeProgress()"/>
    <div v-if="topicStage" class="modal-backdrop centered" @click.self="selectedTopic=undefined"><section class="progress-modal" role="dialog" aria-modal="true" aria-labelledby="topic-title"><button class="drawer-close icon-button" aria-label="关闭主题选择" @click="selectedTopic=undefined"><X :size="20"/></button><BookOpen class="modal-symbol" :size="28"/><h2 id="topic-title">{{topicStage.title}}</h2><p>{{topicStage.summary??'将开放该阶段及前面的蒙德精选片段。'}}</p><p>主题标题和讲解内容可能包含后续线索。确认后新建一段独立对话，原对话保留在历史中。</p><button class="button primary full-width" :disabled="busy" @click="startTopic">按此范围开始对话</button></section></div>
  </div>
</template>
